"""Constructor-based circle packing for n=26 circles (pure Python, no deps)."""
import math


def _dist(a, b):
    return math.hypot(a[0] - b[0], a[1] - b[1])


def _max_radii_feasible(centers):
    """Return radii guaranteeing r_i + r_j <= d_ij and r_i <= wall_i (pure Python)."""
    n = len(centers)
    walls = [min(c[0], 1.0 - c[0], c[1], 1.0 - c[1]) for c in centers]
    D = [[0.0] * n for _ in range(n)]
    for i in range(n):
        D[i][i] = float('inf')
        for j in range(i + 1, n):
            d = _dist(centers[i], centers[j])
            D[i][j] = d
            D[j][i] = d

    r = [float('inf')] * n
    for _ in range(2000):
        new_r = [0.0] * n
        for i in range(n):
            m = float('inf')
            for j in range(n):
                if i != j:
                    v = D[i][j] - r[j]
                    if v < m:
                        m = v
            new_r[i] = m if m > 0.0 else 0.0
        diff = max(abs(new_r[i] - r[i]) for i in range(n))
        r = new_r
        if diff < 1e-13:
            break

    lo, hi = 0.0, 1.0
    for _ in range(60):
        mid = 0.5 * (lo + hi)
        viol = 0.0
        for i in range(n):
            for j in range(n):
                if i != j:
                    v = mid * r[i] + mid * r[j] - D[i][j]
                    if v > viol:
                        viol = v
        if viol > 1e-9:
            hi = mid
        else:
            lo = mid
    rr = [lo * r[i] for i in range(n)]
    for i in range(n):
        if rr[i] > walls[i]:
            rr[i] = walls[i]
        rr[i] *= 0.999999
        if rr[i] < 0.0:
            rr[i] = 0.0
    return rr


def _grid_centers(row_counts, x_lo, x_hi, y_lo, y_hi):
    total = sum(row_counts)
    centers = []
    n_rows = len(row_counts)
    for ri, cnt in enumerate(row_counts):
        y = y_lo + (y_hi - y_lo) * (ri + 0.5) / n_rows
        if cnt == 1:
            xs = [0.5]
        else:
            xs = [x_lo + (x_hi - x_lo) * k / (cnt - 1) for k in range(cnt)]
        for x in xs:
            centers.append([x, y])
    return centers


def construct_packing():
    n = 26
    try:
        bases = [
            _grid_centers([6, 5, 5, 5, 5], 0.08, 0.92, 0.06, 0.94),
            _grid_centers([5, 6, 5, 5, 5], 0.08, 0.92, 0.06, 0.94),
            _grid_centers([5, 5, 6, 5, 5], 0.08, 0.92, 0.06, 0.94),
        ]
        best_centers = None
        best_radii = None
        best_sum = -1.0
        for base in bases:
            r = _max_radii_feasible(base)
            s = sum(r)
            if s > best_sum:
                best_sum = s
                best_centers = [c[:] for c in base]
                best_radii = r[:]
        return best_centers, best_radii, best_sum
    except Exception:
        centers = []
        for i in range(5):
            for j in range(5):
                centers.append([0.1 + i * 0.2, 0.1 + j * 0.2])
        centers.append([0.5, 0.5])
        radii = [0.02] * 26
        return centers, radii, sum(radii)

