"""Constructor-based circle packing for n=26 circles (pure Python, no deps)."""
import math


def _dist(a, b):
    return math.hypot(a[0] - b[0], a[1] - b[1])


def _lp_max_sum(A, b, n):
    """Maximize sum(x_i) s.t. A x <= b, x >= 0, via pure-Python simplex.
    Returns (value, x) or (None, None) if infeasible/unbounded."""
    m = len(A)
    # tableau: rows of length n + m + 1 (last = RHS). cols: x(0..n-1), slacks(n..n+m-1), RHS
    T = [[0.0] * (n + m + 1) for _ in range(m + 1)]
    for i in range(m):
        for j in range(n):
            T[i][j] = A[i][j]
        T[i][n + i] = 1.0
        T[i][n + m] = b[i]
    for j in range(n):
        T[m][j] = -1.0  # objective: maximize sum -> min -sum

    def pivot(r, c):
        piv = T[r][c]
        for k in range(n + m + 1):
            T[r][k] /= piv
        for i in range(m + 1):
            if i != r and T[i][c] != 0.0:
                f = T[i][c]
                for k in range(n + m + 1):
                    T[i][k] -= f * T[r][k]

    for _ in range(50000):
        # choose entering col (most negative objective coeff, Bland tiebreak)
        c = -1
        best = -1e-12
        for j in range(n + m):
            if T[m][j] < best:
                best = T[m][j]
                c = j
        if c == -1:
            break
        # choose leaving row (min ratio)
        r = -1
        best_ratio = float('inf')
        for i in range(m):
            if T[i][c] > 1e-12:
                ratio = T[i][n + m] / T[i][c]
                if ratio < best_ratio - 1e-12:
                    best_ratio = ratio
                    r = i
        if r == -1:
            return None, None  # unbounded
        pivot(r, c)
    x = [T[m + 1 - 1][j] if False else 0.0 for j in range(n)]
    # basic variable values: find which x-col is basic in each row
    x = [0.0] * n
    for i in range(m):
        # basic col = the col with a 1 in row i among x and slack (simplex keeps unit)
        # read RHS assigned to basic var; if basic var is an x_j, set x_j
        for j in range(n + m):
            if abs(T[i][j] - 1.0) < 1e-9:
                if j < n:
                    x[j] = T[i][n + m]
                break
    val = -T[m][n + m]
    return val, x


def _optimal_radii(centers):
    """Solve the radius LP exactly for fixed centers; fallback to safe scale."""
    n = len(centers)
    walls = [min(c[0], 1.0 - c[0], c[1], 1.0 - c[1]) for c in centers]
    A = []
    b = []
    for i in range(n):
        for j in range(i + 1, n):
            d = _dist(centers[i], centers[j])
            row = [0.0] * n
            row[i] = 1.0
            row[j] = 1.0
            A.append(row)
            b.append(d)
    for i in range(n):
        row = [0.0] * n
        row[i] = 1.0
        A.append(row)
        b.append(walls[i])
    try:
        val, x = _lp_max_sum(A, b, n)
        if val is not None:
            x = [max(0.0, min(xi, walls[i])) for i, xi in enumerate(x)]
            # tiny safety margin
            x = [xi * 0.9999999 for xi in x]
            return x, sum(x)
    except Exception:
        pass
    # fallback: global scale of Jacobi vector
    D = [[0.0] * n for _ in range(n)]
    for i in range(n):
        D[i][i] = float('inf')
        for j in range(i + 1, n):
            d = _dist(centers[i], centers[j])
            D[i][j] = d
            D[j][i] = d
    r = [float('inf')] * n
    for _ in range(2000):
        nr = [0.0] * n
        for i in range(n):
            mval = float('inf')
            for j in range(n):
                if i != j:
                    v = D[i][j] - r[j]
                    if v < mval:
                        mval = v
            nr[i] = mval if mval > 0 else 0.0
        r = nr
    lo, hi = 0.0, 1.0
    for _ in range(50):
        mid = 0.5 * (lo + hi)
        viol = 0.0
        for i in range(n):
            for j in range(i + 1, n):
                v = mid * r[i] + mid * r[j] - D[i][j]
                if v > viol:
                    viol = v
        if viol > 1e-9:
            hi = mid
        else:
            lo = mid
    rr = [min(lo * r[i], walls[i]) * 0.9999999 for i in range(n)]
    return rr, sum(rr)


def _grid_centers(row_counts, x_lo, x_hi, y_lo, y_hi):
    centers = []
    n_rows = len(row_counts)
    for ri, cnt in enumerate(row_counts):
        y = y_lo + (y_hi - y_lo) * (ri + 0.5) / n_rows
        if cnt == 1:
            xs = [0.5]
        else:
            xs = [x_lo + (x_hi - x_lo) * k / (cnt - 1) for k in range(cnt)]
        for x in xs:
            centers.append([x, y])
    return centers


def _local_search(centers, radii, steps=200, lr=0.006):
    """Bounded deterministic local search maximizing sum of optimal radii."""
    n = len(centers)
    best = [c[:] for c in centers]
    best_sum = sum(radii)
    for it in range(steps):
        improved = False
        for i in range(n):
            x, y = best[i]
            for dx in (-lr, 0.0, lr):
                for dy in (-lr, 0.0, lr):
                    if dx == 0.0 and dy == 0.0:
                        continue
                    nx, ny = x + dx, y + dy
                    if nx < 0.001 or nx > 0.999 or ny < 0.001 or ny > 0.999:
                        continue
                    trial = [c[:] for c in best]
                    trial[i] = [nx, ny]
                    tr, ts = _optimal_radii(trial)
                    if ts > best_sum + 1e-10:
                        best = trial
                        best_sum = ts
                        improved = True
        if not improved:
            lr *= 0.75
            if lr < 1e-4:
                break
    return best, best_sum


def construct_packing():
    n = 26
    try:
        bases = [
            _grid_centers([6, 5, 5, 5, 5], 0.08, 0.92, 0.06, 0.94),
            _grid_centers([5, 6, 5, 5, 5], 0.08, 0.92, 0.06, 0.94),
            _grid_centers([5, 5, 6, 5, 5], 0.08, 0.92, 0.06, 0.94),
            _grid_centers([6, 5, 5, 5, 5], 0.06, 0.94, 0.05, 0.95),
        ]
        best_centers = None
        best_radii = None
        best_sum = -1.0
        for base in bases:
            r, s = _optimal_radii(base)
            if s > best_sum:
                best_sum = s
                best_centers = [c[:] for c in base]
                best_radii = r[:]
        # local search from best base
        lc, ls = _local_search(best_centers, best_radii, steps=150, lr=0.006)
        if ls > best_sum:
            best_centers = lc
            best_sum = ls
            best_radii, _ = _optimal_radii(lc)
        return best_centers, best_radii, best_sum
    except Exception:
        centers = []
        for i in range(5):
            for j in range(5):
                centers.append([0.1 + i * 0.2, 0.1 + j * 0.2])
        centers.append([0.5, 0.5])
        radii = [0.02] * 26
        return centers, radii, sum(radii)

