"""Constructor-based circle packing for n=26 circles (pure Python, no deps)."""
import math


def _dist(a, b):
    return math.hypot(a[0] - b[0], a[1] - b[1])


def _solve_dual(centers):
    """Minimize sum(d_i) s.t. d_i+d_j >= 1 (i<j), d_i >= w_i/d_i, d_i >= 0.
    Active-set (KKT) pure Python. Returns sum(d) or None on failure."""
    n = len(centers)
    d = [0.0] * n
    for i in range(n):
        c = centers[i]
        w = min(c[0], 1.0 - c[0], c[1], 1.0 - c[1])
        d[i] = max(1e-6, w / 1.0)  # start from wall constraint (d_i >= w_i / r_i with r_i=w_i -> d_i=1? no)
    # Actually wall constraint: r_i <= w_i -> d_i = 1/r_i >= 1/w_i
    for i in range(n):
        c = centers[i]
        w = min(c[0], 1.0 - c[0], c[1], 1.0 - c[1])
        d[i] = max(1e-6, 1.0 / w) if w > 0 else 1e6
    # active-set iterations
    for it in range(2000):
        # find most violated constraint
        worst = -1.0
        wtype = 0  # 0 none, 1 pair, 2 wall
        wi = wj = -1
