"""Constructor-based circle packing for n=26 circles (pure Python, no deps)."""
import math


def _dist(a, b):
    return math.hypot(a[0] - b[0], a[1] - b[1])


def _fast_radii(centers):
    """Fast guaranteed-feasible radii: global scale of Jacobi vector, wall-capped."""
    n = len(centers)
    walls = [min(c[0], 1.0 - c[0], c[1], 1.0 - c[1]) for c in centers]
    D = [[0.0] * n for _ in range(n)]
    for i in range(n):
        D[i][i] = float('inf')
        for j in range(i + 1, n):
            d = _dist(centers[i], centers[j])
            D[i][j] = d
            D[j][i] = d
    r = [float('inf')] * n
    for _ in range(1000):
        nr = [0.0] * n
        for i in range(n):
            mval = float('inf')
            for j in range(n):
                if i != j:
                    v = D[i][j] - r[j]
                    if v < mval:
                        mval = v
            nr[i] = mval if mval > 0 else 0.0
        diff = max(abs(nr[i] - r[i]) for i in range(n))
        r = nr
        if diff < 1e-12:
            break
    lo, hi = 0.0, 1.0
    for _ in range(50):
        mid = 0.5 * (lo + hi)
        viol = 0.0
        for i in range(n):
            for j in range(i + 1, n):
                v = mid * r[i] + mid * r[j] - D[i][j]
                if v > viol:
                    viol = v
        if viol > 1e-9:
            hi = mid
        else:
            lo = mid
    rr = [min(lo * r[i], walls[i]) * 0.9999999 for i in range(n)]
    return rr


def _approx_sum(centers):
    """Cheap objective for local search: fast radii sum (feasible)."""
    return sum(_fast_radii(centers))


def _grid_centers(row_counts, x_lo, x_hi, y_lo, y_hi):
    centers = []
    n_rows = len(row_counts)
    for ri, cnt in enumerate(row_counts):
        y = y_lo + (y_hi - y_lo) * (ri + 0.5) / n_rows
        if cnt == 1:
            xs = [0.5]
        else:
            xs = [x_lo + (x_hi - x_lo) * k / (cnt - 1) for k in range(cnt)]
        for x in xs:
            centers.append([x, y])
    return centers


def _local_search(centers, steps=120, lr=0.008):
    """Bounded local search using the fast feasible objective."""
    n = len(centers)
    best = [c[:] for c in centers]
    best_sum = _approx_sum(best)
    for it in range(steps):
        improved = False
        for i in range(n):
            x, y = best[i]
            for dx in (-lr, 0.0, lr):
                for dy in (-lr, 0.0, lr):
                    if dx == 0.0 and dy == 0.0:
                        continue
                    nx, ny = x + dx, y + dy
                    if nx < 0.001 or nx > 0.999 or ny < 0.001 or ny > 0.999:
                        continue
                    trial = [c[:] for c in best]
                    trial[i] = [nx, ny]
                    ts = _approx_sum(trial)
                    if ts > best_sum + 1e-10:
                        best = trial
